 const hipY=L*.98,shoulderY=H*.79,neckY=H*.86,headY=H*.925,torsoH=shoulderY-hipY,torsoW=C/Math.PI*.84,hipW=HP/Math.PI*.76,shoulderX=torsoW*.7,armX=shoulderX+.085,upperY=shoulderY-A*.24,foreY=shoulderY-A*.61,handY=shoulderY-A*.88,legX=hipW*.42,thighY=L*.78,shinY=L*.32;
