 let g=group('collar');cyl(g,torsoW*.65,torsoW*.75,.055,trim,0,neckY-.03,0);for(const s of [-1,1]){ball(g,.17,.065,.18,trim,s*shoulderX,shoulderY+.005,0);box(g,.13,.032,.13,mat,s*shoulderX,shoulderY+.04,.025)}
