function patternDimensions(id){const m=state.m;const r={collar:[m.chest*.46,7],chest:[m.chest*.54,(m.height-m.leg)*.47],ribs:[m.chest*.16,(m.height-m.leg)*.35],biceps:[m.chest*.31,m.arm*.25],forearms:[m.chest*.28,m.arm*.32],hands:[m.chest*.13,m.arm*.18],belt:[m.hips*.56,12],thighs:[m.hips*.43,m.leg*.33],shins:[m.hips*.30,m.leg*.32],feet:[m.hips*.22,m.leg*.22]};return r[id]}
