document.getElementById('exportSvg').onclick=()=>{const chosen=parts.filter(([id])=>state.visible[id]);if(!chosen.length){alert('Activa al menos una pieza.');return}for(const [id,label,count] of chosen){const [cw,ch]=patternDimensions(id);const w=Math.round(cw*10),h=Math.round(ch*10),pad=25,outerW=w+pad*2,outerH=h+105;let poly=id==='chest'?`${pad},${pad+30} ${pad+w*.18},${pad} ${pad+w*.82},${pad} ${pad+w},${pad+30} ${pad+w*.92},${pad+h} ${pad+w*.08},${pad+h}`:id==='thighs'||id==='shins'||id==='forearms'?`${pad+15},${pad} ${pad+w-15},${pad} ${pad+w},${pad+h} ${pad},${pad+h}`:`${pad},${pad} ${pad+w},${pad} ${pad+w},${pad+h} ${pad},${pad+h}`;let svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${outerW}mm" height="${outerH}mm" viewBox="0 0 ${outerW} ${outerH}"><rect width="100%" height="100%" fill="white"/><text x="25" y="${h+pad+22}" font-family="Arial" font-size="12">HEV Mayer · ${label} · ${count} · ${w} × ${h} mm</text><text x="25" y="${h+pad+39}" font-family="Arial" font-size="8">Patrón preliminar. Probar en papel. Añadir pestañas, uniones y holgura según material.</text><polygon points="${poly}" fill="none" stroke="black" stroke-width="1"/><path d="M25 ${h+pad+50}h50v50h-50z" fill="none" stroke="black" stroke-width=".7"/><text x="83" y="${h+pad+79}" font-family="Arial" font-size="8">Control 50 mm · imprimir al 100 %</text></svg>`;setTimeout(()=>download(`HEV-Mayer-${id}.svg`,svg),chosen.indexOf(parts.find(p=>p[0]===id))*250)}};
